monkey_patch_source.apply_patches:
def apply_patches(cell: dict[str, Any]) -> None:
    """Install/restore the module-level replacements requested by one cell."""
    if cell.get("patch_controller"):
        run_experiment.DSLPIDControl = make_patched_controller(
            float(cell.get("ki_xy", STOCK_KI_XY)), float(cell.get("clamp_xy", STOCK_CLAMP_XY)))
    else:
        run_experiment.DSLPIDControl = _STOCK_CONTROLLER
    run_experiment.DURATION_SEC = float(cell.get("duration_s", _ORIG_DURATION))
    if cell.get("record_assignment"):
        run_experiment.hungarian_assign = hungarian_assign_logged
        run_experiment.WindyCtrlAviary = RecordingWindyCtrlAviary
    else:
        run_experiment.hungarian_assign = _ORIG_HUNGARIAN
        run_experiment.WindyCtrlAviary = _ORIG_AVIARY
    if cell.get("save_trajectory"):
        os.environ["FIRE_SAVE_TRAJECTORY"] = "1"
    else:
        os.environ.pop("FIRE_SAVE_TRAJECTORY", None)

monkey_patch_source.run_cell:
def run_cell(cell: dict[str, Any]) -> dict[str, Any]:
    """Run one episode of the frozen code under the patches described by ``cell``."""
    apply_patches(cell)
    _A7_STATE["log"] = []
    _A7_STATE["true_wind"] = None
    t0 = time.perf_counter()
    # BaseAviary prints its URDF parameters on every construction; keep worker stdout quiet.
    with contextlib.redirect_stdout(io.StringIO()):
        row = run_experiment.run_episode(
            str(cell["treatment"]),
            float(cell["force_N"]),
            int(cell["seed"]),
            num_drones=4,
            gui=False,
            success_radius_m=cell.get("radius_m"),
            record_per_drone_metrics=True,
            record_safety_metrics=bool(cell.get("safety", False)),
        )
    row["wall_clock_sec"] = time.perf_counter() - t0
    row["cell"] = {k: v for k, v in cell.items()}
    row["controller"] = (
        {"class": "stock DSLPIDControl", "ki_xy": STOCK_KI_XY, "clamp_xy": STOCK_CLAMP_XY}
        if not cell.get("patch_controller")
        else {"class": run_experiment.DSLPIDControl.__name__,
              "ki_xy": float(cell.get("ki_xy", STOCK_KI_XY)),
              "clamp_xy": float(cell.get("clamp_xy", STOCK_CLAMP_XY))}
    )
    if cell.get("record_assignment"):
        row["assignment_log"] = list(_A7_STATE["log"])
    return row
